<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_notifications_available() { return function_exists( 'bp_is_active' ) && bp_is_active( 'notifications' ) && function_exists( 'bp_notifications_get_all_notifications' ); }
function sd_notification_unread_count() { if ( ! sd_notifications_available() || ! is_user_logged_in() ) { return 0; } if ( function_exists( 'bp_notifications_get_unread_notification_count' ) ) { return absint( bp_notifications_get_unread_notification_count( get_current_user_id() ) ); } return 0; }
function sd_notifications_query( $status = 'all', $page = 1, $per_page = 20 ) { if ( ! sd_notifications_available() || ! is_user_logged_in() ) { return array( 'notifications' => array(), 'total' => 0 ); } $args = array( 'user_id' => get_current_user_id(), 'page' => max( 1, absint( $page ) ), 'per_page' => min( 30, max( 1, absint( $per_page ) ) ) ); if ( 'unread' === $status ) { $args['is_new'] = true; } elseif ( 'read' === $status ) { $args['is_new'] = false; } return bp_notifications_get_all_notifications( $args ); }
function sd_notification_label( $notification ) { $component = isset( $notification->component_name ) ? $notification->component_name : ''; $action = isset( $notification->component_action ) ? $notification->component_action : ''; $map = array( 'friends' => __( 'Friend connection update', 'social-discovery' ), 'groups' => __( 'Community update', 'social-discovery' ), 'activity' => __( 'Activity update', 'social-discovery' ), 'messages' => __( 'New private message', 'social-discovery' ) ); return isset( $map[ $component ] ) ? $map[ $component ] : __( 'New notification', 'social-discovery' ); }
function sd_notification_url( $notification ) { return ! empty( $notification->href ) ? $notification->href : sd_home_url( 'notifications' ); }
